SELECT 'backend-csharp_dotnet-s1-set2', 'csharp_dotnet', 1, 2, 2, 'What is deferred execution in LINQ? Show how it can surprise you, for example when enumerating a query twice or modifying the source after defining the query.', 'technical', 180, 'A LINQ query over IEnumerable is only a description until it is enumerated (foreach, ToList, Count, First). Each enumeration re-runs the pipeline, so side effects or expensive sources repeat and changes to the source between definition and enumeration are visible. Materialise with ToList or ToArray when you need a snapshot or to avoid multiple enumeration.', NULL, NOW(), NOW() FROM DUAL
