SELECT 'backend-csharp_dotnet-s1-set3', 'csharp_dotnet', 1, 3, 4, 'Managed code has a garbage collector, yet applications still leak memory. Give common causes of memory leaks in .NET and how you would find them.', 'technical', 180, 'Typical causes: event handlers or static events that keep subscribers alive, static collections or caches that grow without bounds, undisposed IDisposable objects, captured variables in long-lived closures, and timers. Find them with a memory profiler or dotnet-gcdump and dotnet-dump, comparing heap snapshots and following the retention path (GC roots) of the growing type.', NULL, NOW(), NOW() FROM DUAL
