SELECT 'backend-csharp_dotnet-s2-set3', 'csharp_dotnet', 2, 3, 4, 'Reflection is flexible but slow. How do attributes, expression trees, compiled delegates and source generators help you get the flexibility without the runtime cost?', 'technical', 180, 'Reflection lookups and invocations are slower and block trimming and AOT. Caching MemberInfo, building compiled delegates from expression trees, or using source generators (for System.Text.Json, logging, regex, DI) moves the work to compile time and produces plain fast code. Attributes provide metadata that generators and frameworks consume.', NULL, NOW(), NOW() FROM DUAL
