SELECT 'backend-csharp_dotnet-s3-set2', 'csharp_dotnet', 3, 2, 3, 'Why can you not await inside a lock statement, and how do you limit concurrent async operations with SemaphoreSlim?', 'technical', 180, 'lock uses Monitor, which is thread-affine and cannot be held across an await because the continuation may run on a different thread; the compiler forbids it. SemaphoreSlim.WaitAsync lets you throttle async work (for example at most 5 concurrent HTTP calls) and must be released in a finally block.', NULL, NOW(), NOW() FROM DUAL
