SELECT 'backend-csharp_dotnet-s3-set3', 'csharp_dotnet', 3, 3, 1, 'A .NET service in production shows steadily rising memory and occasional high CPU. Describe your step-by-step diagnosis using metrics, dumps and traces.', 'scenario', 180, 'Start with runtime metrics (dotnet-counters: GC heap size, gen 2 collections, allocation rate, thread pool queue length), reproduce under load, capture dotnet-gcdump or a dump and compare snapshots to find types growing and their roots, use dotnet-trace or a profiler for CPU hot paths, then fix and verify with the same measurements. Check for event handler leaks, static caches, undisposed objects and unbounded queues.', NULL, NOW(), NOW() FROM DUAL
