SELECT 'backend-csharp_dotnet-s3-set3', 'csharp_dotnet', 3, 3, 3, 'Plan an upgrade of a large application from .NET 6 to a current LTS version with minimal risk. What do you check and how do you roll it out?', 'architecture', 180, 'Review the breaking-change and deprecation notes, update the SDK and global.json, run the .NET Upgrade Assistant or analyzers, update packages and test dependencies, enable warnings as errors for obsolete APIs, run the full test suite and load tests, deploy to staging with canary or blue-green releases and watch metrics. Prefer LTS releases and plan the next upgrade before support ends.', NULL, NOW(), NOW() FROM DUAL
