SELECT 'backend-csharp_dotnet-s3-set3', 'csharp_dotnet', 3, 3, 4, 'What happens when a background Task throws an exception that nobody observes, and how should you structure background work so failures are not silently lost?', 'situational', 180, 'Since .NET 4.5 unobserved task exceptions no longer crash the process by default, they are raised through TaskScheduler.UnobservedTaskException when the task is finalised, so failures can vanish. Await tasks, wrap background loops in try/catch with logging, use BackgroundService with a clear failure policy, and monitor with health checks and alerts.', NULL, NOW(), NOW() FROM DUAL
