SELECT 'backend-csharp_dotnet-s3-set3', 'csharp_dotnet', 3, 3, 5, 'Design logging and observability for a .NET microservice: structured logs, correlation IDs, metrics and traces. How do you avoid leaking personal data?', 'architecture', 180, 'Use structured logging (ILogger with message templates, Serilog or built-in providers) with consistent properties, propagate a correlation or trace ID via W3C traceparent, export traces, metrics and logs with OpenTelemetry, and alert on SLO-based signals. Redact or never log secrets and personal data, use log levels and sampling to control volume, and make logs searchable by trace ID.', NULL, NOW(), NOW() FROM DUAL
