SELECT 'backend-aspnet_core-s1-set1', 'aspnet_core', 1, 1, 5, 'How does configuration work in ASP.NET Core? Explain appsettings files, environments, environment variables, user secrets and the IOptions, IOptionsSnapshot and IOptionsMonitor interfaces.', 'technical', 180, 'Configuration providers are layered (appsettings.json, appsettings.{Environment}.json, user secrets in development, environment variables, command line) with later sources overriding earlier ones. The options pattern binds sections to typed classes: IOptions is a singleton read once, IOptionsSnapshot is scoped per request and reloads, IOptionsMonitor is a singleton that notifies on changes. Secrets must never be committed to source control.', NULL, NOW(), NOW() FROM DUAL
