SELECT 'backend-aspnet_core-s1-set2', 'aspnet_core', 1, 2, 2, 'How do you validate input in an ASP.NET Core API? Compare DataAnnotations with FluentValidation, and explain why you use DTOs instead of binding directly to entities (over-posting).', 'technical', 180, 'DataAnnotations are attributes on models; FluentValidation offers richer, testable rules in separate classes. Binding directly to EF entities allows over-posting, where a client sets properties it should not (IsAdmin, price), so use request DTOs with only the allowed fields and map explicitly. Validate on the server regardless of client-side checks.', NULL, NOW(), NOW() FROM DUAL
