SELECT 'backend-aspnet_core-s1-set3', 'aspnet_core', 1, 3, 2, 'Which common web vulnerabilities must an ASP.NET Core developer defend against? Cover CSRF, XSS, SQL injection and CORS misconfiguration.', 'technical', 180, 'CSRF is mitigated with antiforgery tokens for cookie-based apps; XSS by Razor automatic HTML encoding and never rendering untrusted input raw plus a Content Security Policy; SQL injection by parameterised queries (EF Core LINQ, FromSqlInterpolated) rather than string concatenation; CORS by allowing only specific trusted origins instead of any origin with credentials.', NULL, NOW(), NOW() FROM DUAL
