SELECT 'backend-aspnet_core-s1-set3', 'aspnet_core', 1, 3, 3, 'How should passwords and secrets be handled? Explain ASP.NET Core Identity password hashing and where connection strings and API keys should live in development and production.', 'technical', 180, 'Never store passwords in plain text or with fast hashes; ASP.NET Core Identity PasswordHasher uses salted PBKDF2 with many iterations and supports rehashing. Secrets go in user secrets locally and in environment variables or a secret manager (Azure Key Vault, AWS Secrets Manager) in production, ideally with managed identity so no secret is stored in the app at all.', NULL, NOW(), NOW() FROM DUAL
