SELECT 'backend-aspnet_core-s1-set3', 'aspnet_core', 1, 3, 4, 'How do you handle errors and logging in ASP.NET Core? Explain UseExceptionHandler, ILogger levels, structured logging and health check endpoints.', 'technical', 180, 'UseExceptionHandler (or a global exception handler returning ProblemDetails) converts unhandled exceptions into safe responses without leaking stack traces. ILogger with levels (Trace to Critical) and message templates produces structured logs that can be filtered and searched. Health checks expose liveness and readiness endpoints for load balancers and orchestrators.', NULL, NOW(), NOW() FROM DUAL
