SELECT 'backend-aspnet_core-s2-set1', 'aspnet_core', 2, 1, 2, 'Describe advanced dependency injection features: factory registrations, open generics, keyed services in .NET 8 and resolving scoped services inside a singleton or BackgroundService with IServiceScopeFactory.', 'technical', 180, 'Factories create services with runtime logic; open generic registration (IRepository<> to Repository<>) covers many closed types; keyed services let you register several implementations under a key. Singletons and hosted services must create their own scope with IServiceScopeFactory to use scoped services such as DbContext. Enable ValidateScopes and ValidateOnBuild to catch lifetime errors early.', NULL, NOW(), NOW() FROM DUAL
