SELECT 'backend-aspnet_core-s2-set1', 'aspnet_core', 2, 1, 3, 'Why should you use IHttpClientFactory instead of new HttpClient() everywhere? Explain socket exhaustion, DNS changes, typed clients and resilience policies such as retry and circuit breaker.', 'technical', 180, 'Creating and disposing HttpClient per request exhausts sockets (TIME_WAIT) while a single static one ignores DNS changes. IHttpClientFactory pools and rotates handlers, supports named and typed clients and integrates resilience (Polly or Microsoft.Extensions.Http.Resilience) with timeouts, retries with backoff and circuit breakers so one failing dependency does not take down your service.', NULL, NOW(), NOW() FROM DUAL
