SELECT 'backend-aspnet_core-s2-set1', 'aspnet_core', 2, 1, 5, 'How do model binding and minimal API parameter binding work, and how would you implement a custom binder or a reusable endpoint filter for validation?', 'technical', 180, 'Model binders convert request data to parameters (IModelBinder, custom binder providers); minimal APIs bind from route, query, headers, body and services, with BindAsync or TryParse for custom types. An endpoint filter wraps the handler and can validate arguments, short-circuit with a 400 ProblemDetails and be applied to a route group for reuse.', NULL, NOW(), NOW() FROM DUAL
