SELECT 'backend-aspnet_core-s2-set2', 'aspnet_core', 2, 2, 1, 'Design pagination, filtering and versioning for a public REST API. Compare offset and keyset pagination and explain how ETags and RowVersion help with caching and concurrency.', 'technical', 180, 'Offset pagination (skip/take) is simple but slow and unstable on large or changing tables; keyset pagination uses the last seen key and stays fast and consistent. Version the API by URL, header or media type and keep old versions working. ETags allow conditional requests (304) and If-Match checks, while an EF Core concurrency token such as RowVersion detects conflicting updates.', NULL, NOW(), NOW() FROM DUAL
