SELECT 'backend-aspnet_core-s2-set2', 'aspnet_core', 2, 2, 3, 'A list endpoint is slow. Which EF Core query optimisations do you apply: indexes, projections, AsNoTracking, split queries, compiled queries and ExecuteUpdate or ExecuteDelete for bulk operations?', 'technical', 180, 'Look at the generated SQL and execution plan first; add the right indexes, project only needed columns into DTOs, use AsNoTracking for reads, avoid client-side evaluation and loading whole collections, use AsSplitQuery for large includes, compiled queries on hot paths, and ExecuteUpdate and ExecuteDelete to change many rows without loading entities.', NULL, NOW(), NOW() FROM DUAL
