SELECT 'backend-aspnet_core-s2-set2', 'aspnet_core', 2, 2, 4, 'How do you run EF Core migrations safely in production? Discuss idempotent SQL scripts, migration bundles, backward-compatible (expand and contract) changes and rollback.', 'technical', 180, 'Generate reviewed SQL scripts (idempotent) or a migration bundle instead of running Database.Migrate() at app start on many instances. Use expand and contract: add new columns or tables first, deploy code that works with both, backfill, then remove old structures later. Keep a rollback plan, back up before destructive changes and test migrations against production-like data.', NULL, NOW(), NOW() FROM DUAL
