SELECT 'backend-aspnet_core-s2-set3', 'aspnet_core', 2, 3, 2, 'How does the built-in rate limiting middleware work? Compare fixed window, sliding window, token bucket and concurrency limiters and describe protecting a login endpoint.', 'technical', 180, 'Rate limiting policies are registered and applied to endpoints; fixed window counts requests per interval, sliding window smooths the boundary, token bucket allows bursts at a steady refill rate, concurrency limits parallel requests. Partition by user, API key or IP, return 429 with Retry-After, and use stricter limits plus lockout and monitoring on authentication endpoints.', NULL, NOW(), NOW() FROM DUAL
