SELECT 'backend-aspnet_core-s2-set3', 'aspnet_core', 2, 3, 5, 'How do liveness and readiness health checks differ in Kubernetes, and how should an ASP.NET Core app handle graceful termination and configuration in containers?', 'technical', 180, 'Liveness tells the orchestrator whether to restart the container; readiness tells it whether to send traffic (for example when the database is unavailable or a warm-up is not finished). Handle SIGTERM through the host shutdown, stop accepting new requests, finish in-flight work within the shutdown timeout, and read configuration from environment variables or mounted secrets rather than baked-in files.', NULL, NOW(), NOW() FROM DUAL
