SELECT 'backend-aspnet_core-s3-set3', 'aspnet_core', 3, 3, 2, 'An ASP.NET Core service leaks memory over days. Which causes are typical (static caches, HttpClient misuse, event handlers, captured DbContext) and how do you investigate with dotnet-gcdump?', 'scenario', 180, 'Typical causes: unbounded in-memory caches or static collections, subscribing to events without unsubscribing, singletons capturing scoped services, creating many HttpClient instances or large objects on the LOH, and unbounded queues. Take gcdump snapshots at different times, compare object counts and inspect retention paths to the GC root, then fix the owner and add limits or expiry.', NULL, NOW(), NOW() FROM DUAL
