SELECT 'csharp_dotnet', 1, 3, 'What is the difference between const, readonly and static readonly in C#?', 'technical', 180, 'const is a compile-time constant substituted into the code (only primitives and strings); readonly is assigned at declaration or in the constructor so each instance can differ; static readonly is assigned once per type at run time. Changing a const in a library requires recompiling its consumers, which is why public values that may change should be static readonly.', 'document', NULL, NOW(), NOW() FROM DUAL
