SELECT 'csharp_dotnet', 1, 4, 'What do the ref, out and in keywords do when passing parameters to a method?', 'technical', 180, 'ref passes a variable by reference and it must be initialised before the call; out passes by reference and the method must assign it before returning (used for extra return values like TryParse); in passes by reference as read-only, avoiding copies of large structs.', 'document', NULL, NOW(), NOW() FROM DUAL
