SELECT 'csharp_dotnet', 2, 1, 'What is the difference between an array and a List<T> in C#? When do you use each?', 'technical', 180, 'An array has a fixed size and is slightly more efficient; List<T> is a resizable collection with Add, Remove and Insert methods, internally using an array that grows. Use arrays for fixed-size data and performance-critical code, List<T> for most everyday collections.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'csharp_dotnet' AND x.round_number = 2 AND x.position = 1);
