SELECT 'csharp_dotnet', 2, 2, 'How does a Dictionary<TKey, TValue> work internally and what is the average time to look up a value? Why do keys need good GetHashCode and Equals implementations?', 'technical', 180, 'A dictionary hashes the key to find a bucket and then compares keys with Equals, giving average O(1) lookup, insert and removal. Poor hash codes cause many collisions and degrade it towards O(n); keys must have stable hash codes and consistent equality, so mutable keys are dangerous.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'csharp_dotnet' AND x.round_number = 2 AND x.position = 2);
