SELECT 'csharp_dotnet', 2, 3, 'What is LINQ? Show examples of Where, Select, GroupBy and OrderBy, and explain what deferred execution means.', 'technical', 180, 'LINQ is a set of query operators over collections and data sources. Where filters, Select projects, GroupBy groups and OrderBy sorts. Deferred execution means the query runs only when you enumerate it (foreach, ToList, Count), so changes to the source before that point are included and repeated enumeration repeats the work.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'csharp_dotnet' AND x.round_number = 2 AND x.position = 3);
