SELECT 'csharp_dotnet', 3, 1, 'What is the CLR and what does the JIT compiler do? How does .NET (modern) differ from the old .NET Framework?', 'technical', 180, 'The CLR is the runtime that loads assemblies, manages memory, security and execution. C# compiles to IL, and the JIT turns IL into machine code at run time. .NET Framework is Windows-only; modern .NET (formerly .NET Core) is cross-platform, open source, faster and the one where new features are added.', 'document', NULL, NOW(), NOW() FROM DUAL
