SELECT 'csharp_dotnet', 3, 2, 'How does garbage collection work in .NET? What are generations, and why might you still need to dispose of objects?', 'technical', 180, 'The GC automatically frees unused managed objects using generations (0, 1, 2), assuming most objects die young. It does not know about unmanaged resources such as file handles, sockets or database connections, so you implement IDisposable and use using statements to release them promptly.', 'document', NULL, NOW(), NOW() FROM DUAL
