SELECT 'csharp_dotnet', 3, 3, 'What does the using statement do and how do you implement IDisposable in a class?', 'technical', 180, 'using calls Dispose in a finally block when the scope ends, even if an exception occurs. A class that owns disposable or unmanaged resources implements IDisposable with a Dispose method that releases them, and callers wrap instances in using so cleanup is deterministic.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'csharp_dotnet' AND x.round_number = 3 AND x.position = 3);
