SELECT 'csharp_dotnet', 3, 4, 'How should exceptions be handled in C#? Explain try, catch, finally, throw versus throw ex, and custom exceptions.', 'technical', 180, 'Catch only exceptions you can handle, most specific first, use finally for cleanup, and rethrow with throw; to keep the stack trace (throw ex resets it). Create custom exceptions for meaningful domain errors, and avoid using exceptions for normal control flow because they are slow.', 'document', NULL, NOW(), NOW() FROM DUAL
