SELECT 'csharp_dotnet', 3, 5, 'Name some modern C# features you have used such as records, pattern matching, nullable reference types, top-level statements and string interpolation, and explain why they help.', 'technical', 180, 'Records give concise immutable types with value equality; pattern matching and switch expressions simplify branching; nullable reference types find possible null errors at compile time; top-level statements remove boilerplate in small programs; string interpolation makes formatting readable. Together they reduce code and bugs.', 'document', NULL, NOW(), NOW() FROM DUAL
