SELECT 'aspnet_core', 1, 5, 'How do you manage configuration and different environments (Development, Staging, Production) in ASP.NET Core?', 'technical', 180, 'Configuration comes from appsettings.json, appsettings.{Environment}.json, user secrets in development, environment variables and the command line, with later sources overriding earlier ones. The ASPNETCORE_ENVIRONMENT variable selects the environment, and typed settings are read with the options pattern; secrets are never committed.', 'document', NULL, NOW(), NOW() FROM DUAL
