SELECT 'aspnet_core', 2, 2, 'How do you validate request data in an ASP.NET Core API, and why should you use DTOs instead of exposing your database entities?', 'technical', 180, 'Use data annotations such as [Required] and [StringLength], or FluentValidation, and let [ApiController] return a 400 automatically. DTOs expose only the fields the client needs, prevent over-posting (clients setting fields they should not), avoid leaking internal columns and decouple the API contract from the database.', 'document', NULL, NOW(), NOW() FROM DUAL
