SELECT 'aspnet_core', 2, 3, 'What is Entity Framework Core? Explain DbContext, DbSet, migrations and how you would add a new column to a table.', 'technical', 180, 'EF Core is an ORM that maps C# classes to tables. DbContext represents the database session and DbSet<T> a table. Migrations record schema changes as code: to add a column you add the property to the entity, run dotnet ef migrations add, review the generated migration and apply it with dotnet ef database update.', 'document', NULL, NOW(), NOW() FROM DUAL
