SELECT 'aspnet_core', 2, 4, 'How do you load related data in EF Core? Explain Include, lazy loading and why the N+1 problem hurts performance.', 'technical', 180, 'Include loads related entities in the same query using joins; lazy loading fetches related data on first access, which can trigger one extra query per row (the N+1 problem) and slow down lists dramatically. Prefer Include or, better, a Select projection that fetches only the columns needed.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 2 AND x.position = 4);
