SELECT 'aspnet_core', 2, 5, 'Why do we use async and await in controller actions, and what happens if you block with .Result or .Wait()?', 'technical', 180, 'Async actions release the thread while waiting for I/O such as database or HTTP calls, so the server can handle more requests with the same threads. Blocking with .Result or .Wait() holds a thread, which under load exhausts the thread pool, makes requests slow and can cause deadlocks.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 2 AND x.position = 5);
