SELECT 'aspnet_core', 3, 1, 'What is the difference between authentication and authorization in ASP.NET Core? Explain how JWT bearer authentication and the [Authorize] attribute work.', 'technical', 180, 'Authentication verifies who the user is; authorization checks what they can access. With JWT bearer authentication the client sends a signed token in the Authorization header, the middleware validates the signature, issuer, audience and expiry and builds the user from its claims, and [Authorize] (with roles or policies) protects controllers and endpoints.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 3 AND x.position = 1);
