SELECT 'aspnet_core', 3, 2, 'What are CORS and CSRF, and how do you configure or defend against them in ASP.NET Core?', 'technical', 180, 'CORS is a browser mechanism that controls which origins may call your API, configured with AddCors and a policy listing allowed origins, methods and headers (never allow any origin with credentials). CSRF is an attack that abuses cookie authentication to send unwanted requests; defend with antiforgery tokens and SameSite cookies, and it is much less relevant with bearer tokens.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 3 AND x.position = 2);
