SELECT 'aspnet_core', 3, 3, 'How do you handle errors and logging in ASP.NET Core? Mention exception handling middleware, ILogger and log levels.', 'technical', 180, 'Use a global exception handler (UseExceptionHandler) that returns a safe ProblemDetails response instead of stack traces. Inject ILogger<T> and log with levels (Information, Warning, Error, Critical) and structured message templates, sending logs to a central system such as Serilog sinks or Application Insights.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 3 AND x.position = 3);
