SELECT 'aspnet_core', 3, 4, 'How do you deploy an ASP.NET Core application? Explain Kestrel, a reverse proxy such as IIS or Nginx, and a basic Docker deployment.', 'technical', 180, 'Kestrel is the cross-platform web server inside the app; in production it usually sits behind a reverse proxy (IIS, Nginx or a cloud load balancer) that handles TLS and load balancing. With Docker you publish the app, build an image from the official ASP.NET runtime image, expose the port and pass configuration through environment variables.', 'document', NULL, NOW(), NOW() FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM mock_interview_questions x WHERE x.stack_key = 'aspnet_core' AND x.round_number = 3 AND x.position = 4);
INSERT INTO mock_interview_questions (stack_key, round_number, position, text, category, duration_seconds, note, origin, created_by, created_at, updated_at)
SELECT 'aspnet_core', 3, 5, 'How can you improve the performance of an ASP.NET Core application? Mention caching with IMemoryCache, response compression and health checks.', 'technical', 180, 'Cache expensive or frequently read data with IMemoryCache or a distributed cache such as Redis (with sensible expiry), enable response compression, use async I/O, optimise database queries and indexes, and measure before tuning. Health check endpoints help load balancers and orchestrators detect unhealthy instances.', 'document', NULL, NOW(), NOW() FROM DUAL
