-- ---------------------------------------------------------------------------------------------------------------------
-- PART 3 - record the migration so `php artisan migrate` does not run it again
-- ---------------------------------------------------------------------------------------------------------------------
INSERT INTO migrations (migration, batch)
SELECT m.name, (SELECT COALESCE(MAX(batch), 0) + 1 FROM migrations x)
  FROM (SELECT '2026_11_19_100000_add_dotnet_interview_questions' AS name) m
 WHERE NOT EXISTS (SELECT 1 FROM migrations x WHERE x.migration = m.name);

COMMIT;

